INSERT INTO `rating_product` VALUES (1,'Since we implemented this T-shirt as a uniform, we have noticed greater employee satisfaction. They love the comfort and practicality.',4,5,20,'2024-05-21 13:40:44'),(2,'Our outside sales team needs clothes that are comfortable and keep them looking professional all day long. This polyester t-shirt was the perfect choice. Easy to wash, dries quickly and still looks new even after heavy use.',5,5,19,'2024-05-21 13:40:44'),(3,'For our technical support team, practicality and comfort are essential. Since we started wearing these shirts, our employees have reported greater comfort and satisfaction in their daily work. Without a doubt, an excellent choice for corporate uniforms',4,5,8,'2024-05-21 13:40:44');
